BEGIN TRANSACTION;

-- Backfill the two processing states from their detail tables.
-- Derived entirely from existing rows; no judgement, no new facts.

-- captured := at least one row in a joinable evidence table points at this source.
-- jurisdictional_values is deliberately ABSENT from this list: it has no ref_id
-- column (109 rows, all structurally unverifiable). When W5.4 adds that key,
-- this predicate and the C05 check below must both gain the extra leg.
UPDATE evidence_sources SET data_capture_status='captured'
WHERE EXISTS (SELECT 1 FROM source_value_extractions x WHERE x.ref_id = evidence_sources.ref_id)
   OR EXISTS (SELECT 1 FROM spec_value_probes p       WHERE p.ref_id = evidence_sources.ref_id)
   OR EXISTS (SELECT 1 FROM reasoning_doc_citations r WHERE r.source_ref_id = evidence_sources.ref_id)
   OR EXISTS (SELECT 1 FROM economics_entries e       WHERE e.ref_id = evidence_sources.ref_id);

-- mined := a citation-mining pass recorded this source and did not defer it.
UPDATE evidence_sources SET citation_mining_status='mined'
WHERE EXISTS (SELECT 1 FROM citation_mining m
              WHERE m.global_ref_id = evidence_sources.ref_id
                AND COALESCE(m.deferred_reason,'') = '');

-- deferred := every recorded pass for this source was deferred, with a reason.
UPDATE evidence_sources SET citation_mining_status='deferred'
WHERE citation_mining_status='pending'
  AND EXISTS (SELECT 1 FROM citation_mining m
              WHERE m.global_ref_id = evidence_sources.ref_id
                AND COALESCE(m.deferred_reason,'') <> '');

COMMIT;
